import { AgCharts } from 'ag-charts-react';

function RevenueChart() {
  const options = {
    data: [
      { month: 'Jan', revenue: 15200 },
      { month: 'Feb', revenue: 18400 },
      { month: 'Mar', revenue: 22100 },
    ],
    series: [{
      type: 'bar',
      xKey: 'month',
      yKey: 'revenue',
      fill: '#3b82f6',
      cornerRadius: 8,
    }],
  };

  return <AgCharts options={options} />;
}
